using System;
using System.IO;
using System.Linq;
using System.Globalization;
using TTSK_AutoDim_Plates.Keyplan;

// The expected frames were generated by Tekla, not the algorithm under test.
static class MeasuredTests
{
    // Independent projection of two grid intervals onto paper. Check labelled
    // endpoint order and straightness, then classify the visible side by dot products.
    static bool GridOrder(Frame actual,Frame key)
    {
        double dx=V.Dot(key.Right*8000,actual.Right),dy=V.Dot(key.Right*8000,actual.Up);
        double ux=V.Dot(key.Up*5900,actual.Right),uy=V.Dot(key.Up*5900,actual.Up);
        double epsilon=Math.Tan(Geometry.ToleranceDegrees*Math.PI/180);
        V n=V.Cross(actual.Right,actual.Up);
        return dx>0&&uy>0&&Math.Abs(dy)<=epsilon*dx&&Math.Abs(ux)<=epsilon*uy
            &&V.Dot(n,key.Normal)>Math.Max(Math.Abs(V.Dot(n,key.Right)),Math.Abs(V.Dot(n,key.Up)))+1e-8;
    }
    internal static void Run(string dir)
    {
        int count=0,searches=0,projected=0;double max=0;
        foreach(int batch in Directory.GetFiles(dir,"basis-*.txt").Select(p=>int.Parse(Path.GetFileNameWithoutExtension(p).Substring(6))).OrderBy(n=>n))
        {
            var b=File.ReadAllText(Path.Combine(dir,"basis-"+batch+".txt")).Split('\t');
            Func<string,double> parse=s=>double.Parse(s,CultureInfo.InvariantCulture);
            var basis=new Frame(new V(parse(b[0]),parse(b[1]),parse(b[2])),new V(parse(b[3]),parse(b[4]),parse(b[5])));
            // Legacy batch 7 recorded the BEAM/COLUMN enum, not actual vertical
            // placing. Its measured downward BEAM still receives paper rotation.
            bool vertical=Math.Abs(basis.Right.Z)>1-1e-12;
            var rows=File.ReadAllLines(Path.Combine(dir,"frames-"+batch+".tsv")).Skip(1).Select(s=>s.Split('\t')).ToArray();
            if(rows.Length!=64)throw new Exception("Incomplete empirical batch "+batch);
            var observations=rows.Select(v=>new { A=new Angles((int)parse(v[0]),(int)parse(v[1]),parse(v[2])),Type=v[3],
                Frame=new Frame(new V(parse(v[4]),parse(v[5]),parse(v[6])),new V(parse(v[7]),parse(v[8]),parse(v[9]))) }).ToArray();
            var measuredTypes=observations.Select(v=>v.Type).Distinct().OrderBy(t=>t=="FrontView"?0:1).ThenBy(t=>t).ToArray();
            if(measuredTypes.Length!=2)throw new Exception("Expected two empirical view types");
            foreach(var row in observations)
            {
                double err=Geometry.Error(row.Frame,Geometry.LocalView(basis,vertical,row.Type,row.A));max=Math.Max(max,err);count++;
                if(err>Geometry.ToleranceDegrees)throw new Exception("Empirical mismatch batch "+batch+" "+row.A+" "+row.Type+" error="+err);
            }
            foreach(var target in observations.GroupBy(v=>v.A.ToString()))
            {
                var pair=target.ToArray();
                var search=Geometry.SearchLocal(basis,vertical,pair.Select(v=>v.Type).ToArray(),pair.Select(v=>v.Frame).ToArray());searches++;
                var expected=observations.GroupBy(v=>v.A.ToString()).Where(g=>pair.All(t=>Geometry.Error(g.Single(v=>v.Type==t.Type).Frame,t.Frame)<=Geometry.ToleranceDegrees)).Select(g=>g.Key).OrderBy(s=>s);
                if(search.Evaluated.Count!=32||!expected.SequenceEqual(search.Matches.Select(c=>c.Angles.ToString()).OrderBy(s=>s)))throw new Exception("Wrong solution set batch "+batch);
            }
            foreach(int quarter in new[]{0,1,2,3})foreach(int mode in new[]{0,1,2})
            {
                projected++;
                var key=new Frame(new V(1,0,0),new V(0,1,0)).Spin(quarter*90);
                var target=Geometry.Targets(mode==2,mode==1,key);
                var search=Geometry.SearchKeyplan(basis,vertical,measuredTypes,target);
                var expected=observations.GroupBy(v=>v.A.ToString()).Where(g=>GridOrder(g.Single(v=>v.Type==measuredTypes[0]).Frame,target[0])&&GridOrder(g.Single(v=>v.Type==measuredTypes[1]).Frame,target[1])).Select(g=>g.Key).OrderBy(s=>s);
                if(search.Evaluated.Count!=32||!expected.SequenceEqual(search.Matches.Select(c=>c.Angles.ToString()).OrderBy(s=>s)))throw new Exception("Projected grid-order mismatch batch "+batch+" mode="+mode+" turn="+quarter);
                if(batch==1&&quarter==0&&mode<2) {
                    if(mode==0&&search.Matches.Count!=0)throw new Exception("User X sample must report no allowed solution");
                    if(mode==1&&(search.Matches.Count==0||search.Matches[0].Angles.ToString()!=new Angles(0,0,0).ToString()))throw new Exception("User Y sample must recommend Local/0/0/0");
                    Console.WriteLine("CONFIRMED original rolled beam "+(mode==0?"X: S17→S17A / SG-1→SF-1, no solution among 32 tuples":"Y: SG-1→SF-1 / S17A→S17, Local/0/0/0"));
                }
            }
            Console.WriteLine("PASS empirical batch "+batch+": 32 tuples, 64 frames, every inverse solution checked against Tekla output.");
        }
        Console.WriteLine("PASS "+count+" measured view frames / "+searches+" exhaustive searches; max angular error="+max.ToString("R",CultureInfo.InvariantCulture));
        if(count==0)throw new Exception("No measured fixtures");
        Console.WriteLine("PASS "+projected+" projected keyplan searches against independent labelled grid-interval oracle on measured Tekla views.");
    }
}
